=== FILE: deep_counter_formal.sv ===
// Formal wrapper for deep_counter (task prj-784d6227b5:assertions-formal).
// Properties are stated from interface_spec.md section 3, one per requirement
// tag. Inputs are left unconstrained: this file contains no assume statement.
// Immediate assertions only (if-guarded, inside always blocks), with $past
// guarded by f_past_valid.
module deep_counter_formal #(
    parameter integer LIMIT = 99
) (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire clr
);
    localparam [6:0] F_LAST = LIMIT;

    wire [6:0] count;
    wire       carry;

    deep_counter #(.LIMIT(LIMIT)) dut (
        .clk  (clk),
        .rst_n(rst_n),
        .en   (en),
        .clr  (clr),
        .count(count),
        .carry(carry)
    );

    // First-cycle guard for $past.
    reg f_past_valid = 1'b0;
    always @(posedge clk)
        f_past_valid <= 1'b1;

    // Set once a reset edge has happened; the specification's range claim
    // holds "after reset".
    reg f_rst_seen = 1'b0;
    always @(posedge clk)
        if (!rst_n)
            f_rst_seen <= 1'b1;

    // Helper invariant relating the two flags (keeps induction start states
    // consistent).
    always @(*)
        if (f_rst_seen)
            assert(f_past_valid);

    // [req:DC-RANGE] count is never above LIMIT after reset. Also the
    // induction invariant for the unbounded proof.
    always @(*)
        if (f_rst_seen)
            assert(count <= F_LAST);

    // [req:DC-CARRY] carry is high exactly when en, !clr and count == LIMIT,
    // combinationally.
    always @(*)
        assert(carry == (en && !clr && (count == F_LAST)));

    always @(posedge clk) begin
        if (f_past_valid) begin
            // [req:DC-RESET] rst_n low at an edge clears count.
            if (!$past(rst_n))
                assert(count == 7'd0);

            // [req:DC-CLEAR] rst_n high and clr high: count becomes 0,
            // whatever en is.
            if ($past(rst_n) && $past(clr))
                assert(count == 7'd0);

            // [req:DC-COUNT] counting edge: wrap at LIMIT, else increment.
            if ($past(rst_n) && !$past(clr) && $past(en)) begin
                if ($past(count) == F_LAST)
                    assert(count == 7'd0);
                else if ($past(count) < F_LAST)
                    assert(count == $past(count) + 7'd1);
            end

            // [req:DC-HOLD] no clr, no en: count does not change.
            if ($past(rst_n) && !$past(clr) && !$past(en))
                assert(count == $past(count));
        end
    end

    // Covers: scenarios the proof must still allow. Each is guarded by
    // f_rst_seen, so it is reached only along a path from reset and not from
    // an arbitrary initial count.
    always @(posedge clk) begin
        cover(f_rst_seen);
        cover(f_rst_seen && count[6]);
        cover(f_rst_seen && (count == F_LAST));
        cover(f_rst_seen && carry);
        if (f_past_valid) begin
            // Wrap from LIMIT to 0 on a counting edge after reset.
            cover(f_rst_seen && $past(f_rst_seen) && $past(rst_n)
                  && !$past(clr) && $past(en)
                  && ($past(count) == F_LAST) && (count == 7'd0));
            // Clear from a non-zero count.
            cover(f_rst_seen && $past(f_rst_seen) && $past(rst_n)
                  && $past(clr) && ($past(count) != 7'd0));
            // Hold at a non-zero count.
            cover(f_rst_seen && $past(f_rst_seen) && $past(rst_n)
                  && !$past(clr) && !$past(en) && (count != 7'd0));
        end
    end
endmodule
=== END FILE ===
